namespace Contracts.Desktop.Finance;

public sealed class FinancePageViewModel : ObservableObject, INavigationTarget
{
    private readonly FinanceService service; private readonly IPersianDateService dates; private readonly INumberDisplayService numbers; private readonly IConfirmationService confirmation;
    private bool busy, settingSuggested, obligationTypeTouched; private string? error; private int selectedTab; private ObligationRow? selectedObligation; private SettlementRow? selectedSettlement;
    private long obligationContractId, obligationTypeId, obligationAmount; private string obligationDate="", dueDate="", obligationDescription=""; private bool explicitOverride;
    private SettlementKind settlementKind=SettlementKind.Payment; private long settlementContractId, paymentTypeId, settlementAmount; private long? bankId;
    private string settlementNo="", settlementDate="", referenceNo="", invoiceNo="", chequeNo="", payerDescription="", settlementDescription="", attachmentPath="", recordedBy="";
    private long obligationId, obligationVersion, settlementId, settlementVersion;

    public FinancePageViewModel(FinanceService service, IPersianDateService dates, INumberDisplayService numbers, IConfirmationService confirmation)
    {
        this.service=service; this.dates=dates; this.numbers=numbers; this.confirmation=confirmation;
        RefreshCommand=new AsyncRelayCommand(RefreshAsync); NewObligationCommand=new RelayCommand(NewObligation); SaveObligationCommand=new AsyncRelayCommand(SaveObligationAsync); DeleteObligationCommand=new AsyncRelayCommand(DeleteObligationAsync); OpenObligationCommand=new RelayCommand(OpenObligation);
        NewSettlementCommand=new AsyncRelayCommand(NewSettlementAsync); SaveSettlementCommand=new AsyncRelayCommand(SaveSettlementAsync); DeleteSettlementCommand=new AsyncRelayCommand(DeleteSettlementAsync); OpenSettlementCommand=new AsyncRelayCommand(OpenSettlementAsync);
    }
    public ObservableCollection<FinanceContractOption> Contracts { get; }=[]; public ObservableCollection<SimpleLookupDto> TransactionTypes { get; }=[]; public ObservableCollection<SimpleLookupDto> Statuses { get; }=[]; public ObservableCollection<SimpleLookupDto> PaymentTypes { get; }=[]; public ObservableCollection<SimpleLookupDto> Banks { get; }=[];
    public ObservableCollection<ObligationRow> Obligations { get; }=[]; public ObservableCollection<SettlementRow> Settlements { get; }=[]; public ObservableCollection<AllocationEditor> AllocationEditors { get; }=[];
    public int SelectedTab { get=>selectedTab; set { if(SetProperty(ref selectedTab,value)&&value>0) SettlementKind=value==1?SettlementKind.Payment:SettlementKind.Receipt; } } public bool IsBusy { get=>busy; private set=>SetProperty(ref busy,value); } public string? ErrorMessage { get=>error; private set { if(SetProperty(ref error,value)) OnPropertyChanged(nameof(HasError)); } } public bool HasError=>!string.IsNullOrWhiteSpace(ErrorMessage);
    public ObligationRow? SelectedObligation { get=>selectedObligation; set=>SetProperty(ref selectedObligation,value); } public SettlementRow? SelectedSettlement { get=>selectedSettlement; set=>SetProperty(ref selectedSettlement,value); }
    public long ObligationContractId { get=>obligationContractId; set { if(SetProperty(ref obligationContractId,value)){OnPropertyChanged(nameof(ObligationContractContext));if(obligationId==0&&!obligationTypeTouched)ApplySuggestedType();} } } public long ObligationTypeId { get=>obligationTypeId; set { if(SetProperty(ref obligationTypeId,value)&&!settingSuggested)obligationTypeTouched=true; } } public long ObligationAmount { get=>obligationAmount; set=>SetProperty(ref obligationAmount,value); }
    public string ObligationContractContext=>Contracts.FirstOrDefault(x=>x.Id==ObligationContractId) is { } c?$"{c.TypeTitle} | {c.PartyName}":"";
    public string ObligationDate { get=>obligationDate; set=>SetProperty(ref obligationDate,value); } public string DueDate { get=>dueDate; set=>SetProperty(ref dueDate,value); } public string ObligationDescription { get=>obligationDescription; set=>SetProperty(ref obligationDescription,value); } public bool ExplicitTypeOverride { get=>explicitOverride; set=>SetProperty(ref explicitOverride,value); }
    public SettlementKind SettlementKind { get=>settlementKind; set { if(SetProperty(ref settlementKind,value)) _=ReloadSettlementModeAsync(); } } public bool IsPayment=>SettlementKind==SettlementKind.Payment;
    public long SettlementContractId { get=>settlementContractId; set { if(SetProperty(ref settlementContractId,value)){OnPropertyChanged(nameof(SettlementContractContext));_=LoadAllocationCandidatesAsync();} } } public string SettlementContractContext=>Contracts.FirstOrDefault(x=>x.Id==SettlementContractId) is { } c?$"{c.TypeTitle} | {c.PartyName}":""; public long PaymentTypeId { get=>paymentTypeId; set { if(SetProperty(ref paymentTypeId,value)) { OnPropertyChanged(nameof(IsCheque)); OnPropertyChanged(nameof(IsBankTransfer)); } } }
    public long SettlementAmount { get=>settlementAmount; set { if(SetProperty(ref settlementAmount,value)) OnPropertyChanged(nameof(UnallocatedDisplay)); } } public long? BankId { get=>bankId; set=>SetProperty(ref bankId,value); }
    public string SettlementNo { get=>settlementNo; set=>SetProperty(ref settlementNo,value); } public string SettlementDate { get=>settlementDate; set=>SetProperty(ref settlementDate,value); } public string ReferenceNo { get=>referenceNo; set=>SetProperty(ref referenceNo,value); } public string InvoiceNo { get=>invoiceNo; set=>SetProperty(ref invoiceNo,value); } public string ChequeNo { get=>chequeNo; set=>SetProperty(ref chequeNo,value); } public string PayerDescription { get=>payerDescription; set=>SetProperty(ref payerDescription,value); } public string SettlementDescription { get=>settlementDescription; set=>SetProperty(ref settlementDescription,value); } public string AttachmentPath { get=>attachmentPath; set=>SetProperty(ref attachmentPath,value); } public string RecordedBy { get=>recordedBy; private set=>SetProperty(ref recordedBy,value); }
    public bool IsCheque=>PaymentTypes.FirstOrDefault(x=>x.Id==PaymentTypeId)?.Code=="CHEQUE"; public bool IsBankTransfer=>PaymentTypes.FirstOrDefault(x=>x.Id==PaymentTypeId)?.Code=="BANK_TRANSFER";
    public string UnallocatedDisplay { get { long allocated=AllocationEditors.Aggregate(0L,(s,x)=>checked(s+x.AmountRial)); return numbers.FormatMoney(FinancialProjectionPolicy.Difference(SettlementAmount,allocated)); } }
    public IAsyncRelayCommand RefreshCommand{get;} public IRelayCommand NewObligationCommand{get;} public IAsyncRelayCommand SaveObligationCommand{get;} public IAsyncRelayCommand DeleteObligationCommand{get;} public IRelayCommand OpenObligationCommand{get;} public IAsyncRelayCommand NewSettlementCommand{get;} public IAsyncRelayCommand SaveSettlementCommand{get;} public IAsyncRelayCommand DeleteSettlementCommand{get;} public IAsyncRelayCommand OpenSettlementCommand{get;}
    public void ActivateRoute(string route) { SelectedTab=route=="ledger"?0:route=="payments"?1:2; }
    public async Task OnNavigatedToAsync(CancellationToken cancellationToken) { FinanceReferenceData r=await service.ReferencesAsync(cancellationToken); Replace(Contracts,r.Contracts);Replace(TransactionTypes,r.TransactionTypes);Replace(Statuses,r.Statuses);Replace(PaymentTypes,r.PaymentTypes);Replace(Banks,r.Banks); await RefreshAsync(cancellationToken); }
    private async Task RefreshAsync(CancellationToken ct)=>await Run(async()=>{ PageResult<ObligationRow> l=await service.SearchObligationsAsync(new(PageSize:100),ct);Replace(Obligations,l.Items);PageResult<SettlementRow>s=await service.SearchSettlementsAsync(SettlementKind,null,1,100,ct);Replace(Settlements,s.Items); });
    private void NewObligation(){obligationId=obligationVersion=0;obligationTypeTouched=false;ObligationContractId=Contracts.FirstOrDefault()?.Id??0;ApplySuggestedType();ObligationDate=DueDate="";ObligationAmount=0;ObligationDescription="";ExplicitTypeOverride=false;}
    private void OpenObligation(){if(SelectedObligation is null)return;var x=SelectedObligation;obligationId=x.Id;obligationVersion=x.ConcurrencyVersion;ObligationContractId=x.ContractId;settingSuggested=true;ObligationTypeId=x.TransactionTypeId;settingSuggested=false;obligationTypeTouched=false;ObligationDate=dates.Format(x.TransactionDate);DueDate=dates.Format(x.DueDate);ObligationAmount=x.AmountRial;ObligationDescription=x.Description??"";ExplicitTypeOverride=false;}
    private void ApplySuggestedType(){long? suggested=FinanceService.SuggestedType(Contracts.FirstOrDefault(x=>x.Id==ObligationContractId)?.TypeCode??"");if(!suggested.HasValue)return;settingSuggested=true;ObligationTypeId=suggested.Value;settingSuggested=false;}
    private async Task SaveObligationAsync(CancellationToken ct)=>await Run(async()=>{DateOnly date=Parse(ObligationDate),due=Parse(DueDate);if(obligationId==0)await service.CreateObligationAsync(new(ObligationContractId,ObligationTypeId,date,due,ObligationAmount,ObligationDescription,ExplicitTypeOverride),ct);else await service.UpdateObligationAsync(new(obligationId,obligationVersion,date,due,ObligationAmount,ObligationDescription),ct);await RefreshAsync(ct);});
    private async Task DeleteObligationAsync(CancellationToken ct){if(obligationId==0||!await confirmation.ConfirmAsync("این تعهد حذف شود؟",ct))return;await Run(async()=>{await service.DeleteObligationAsync(obligationId,obligationVersion,ct);NewObligation();await RefreshAsync(ct);});}
    private async Task ReloadSettlementModeAsync(){OnPropertyChanged(nameof(IsPayment));await NewSettlementAsync(CancellationToken.None);await RefreshAsync(CancellationToken.None);}
    private async Task NewSettlementAsync(CancellationToken ct){settlementId=settlementVersion=0;SettlementContractId=Contracts.FirstOrDefault()?.Id??0;PaymentTypeId=PaymentTypes.FirstOrDefault()?.Id??0;SettlementNo=SettlementDate=ReferenceNo=InvoiceNo=ChequeNo=PayerDescription=SettlementDescription=AttachmentPath=RecordedBy="";SettlementAmount=0;BankId=null;await LoadAllocationCandidatesAsync(ct);}
    private async Task LoadAllocationCandidatesAsync(CancellationToken ct=default){if(SettlementContractId<=0)return;try{IReadOnlyList<ObligationRow> rows=await service.OpenObligationsAsync(SettlementContractId,SettlementKind,ct);AllocationEditors.Clear();foreach(var x in rows)AllocationEditors.Add(new(x.Id,x.TransactionNo,x.DueDate,x.RemainingAmountRial,0,NotifyAllocation));NotifyAllocation();}catch(Exception ex){ErrorMessage=MasterData.MasterDataErrorMapper.Map(ex);}}
    private async Task SaveSettlementAsync(CancellationToken ct)=>await Run(async()=>{SettlementInput v=new(SettlementContractId,SettlementNo,Parse(SettlementDate),SettlementAmount,PaymentTypeId,BankId,ReferenceNo,InvoiceNo,ChequeNo,PayerDescription,SettlementDescription,AttachmentPath,AllocationEditors.Where(x=>x.AmountRial>0).Select(x=>new AllocationInput(x.ObligationId,x.AmountRial)).ToList());if(settlementId==0)await service.CreateSettlementAsync(SettlementKind,v,ct);else await service.UpdateSettlementAsync(SettlementKind,new(settlementId,settlementVersion,v),ct);await NewSettlementAsync(ct);await RefreshAsync(ct);});
    private async Task OpenSettlementAsync(CancellationToken ct){if(SelectedSettlement is null)return;await Run(async()=>{SettlementRow x=await service.GetSettlementAsync(SettlementKind,SelectedSettlement.Id,ct)??throw new KeyNotFoundException();settlementId=x.Id;settlementVersion=x.ConcurrencyVersion;SettlementContractId=x.ContractId;SettlementNo=x.Number;SettlementDate=dates.Format(x.Date);SettlementAmount=x.AmountRial;PaymentTypeId=PaymentTypes.First(y=>y.TitleFa==x.PaymentTypeTitle).Id;BankId=string.IsNullOrEmpty(x.BankTitle)?null:Banks.First(y=>y.TitleFa==x.BankTitle).Id;ReferenceNo=x.ReferenceNo??"";InvoiceNo=x.InvoiceNo??"";ChequeNo=x.ChequeNo??"";PayerDescription=x.PayerDescription??"";SettlementDescription=x.Description??"";AttachmentPath=x.AttachmentPath??"";RecordedBy=$"{x.RecordedByDisplayName} - {x.RecordedAtUtc:yyyy-MM-dd HH:mm} UTC";await LoadAllocationCandidatesAsync(ct);foreach(var a in x.Allocations){AllocationEditor? e=AllocationEditors.FirstOrDefault(y=>y.ObligationId==a.ObligationId);if(e is null){e=new(a.ObligationId,a.TransactionNo,a.DueDate,a.ObligationRemainingAfterRial+a.AmountRial,a.AmountRial,NotifyAllocation);AllocationEditors.Add(e);}else e.AmountRial=a.AmountRial;}NotifyAllocation();});}
    private async Task DeleteSettlementAsync(CancellationToken ct){if(settlementId==0||!await confirmation.ConfirmAsync("این پرداخت/دریافت حذف و تخصیص‌های آن آزاد شود؟",ct))return;await Run(async()=>{await service.DeleteSettlementAsync(SettlementKind,settlementId,settlementVersion,ct);await NewSettlementAsync(ct);await RefreshAsync(ct);});}
    private DateOnly Parse(string value)=>dates.TryParse(value,out DateOnly d)?d:throw new MasterDataValidationException(["تاریخ باید شمسی و به شکل yyyy/MM/dd باشد."]);
    private void NotifyAllocation()=>OnPropertyChanged(nameof(UnallocatedDisplay)); private async Task Run(Func<Task> a){IsBusy=true;ErrorMessage=null;try{await a();}catch(Exception ex){ErrorMessage=MasterData.MasterDataErrorMapper.Map(ex);}finally{IsBusy=false;}}
    private static void Replace<T>(ObservableCollection<T> t,IEnumerable<T>s){t.Clear();foreach(T x in s)t.Add(x);}
}

public sealed class AllocationEditor : ObservableObject
{
    private long amount; private readonly Action changed; public AllocationEditor(long id,string no,DateOnly due,long remaining,long amount,Action changed){ObligationId=id;TransactionNo=no;DueDate=due;RemainingRial=remaining;this.amount=amount;this.changed=changed;}
    public long ObligationId{get;} public string TransactionNo{get;} public DateOnly DueDate{get;} public long RemainingRial{get;} public long AmountRial{get=>amount;set{if(SetProperty(ref amount,value))changed();}}
}
